// 闪记核心数据类型定义

// 学科大类（用于 SM-2 参数调制）
export type SubjectPreset = "语言类" | "文科类" | "理科公式" | "理科概念";

// 知识点
export interface KnowledgePoint {
  id: string;
  title: string;
  preset: SubjectPreset;
  // 展示用学科名（历史 / 化学 / 英语 / 数学 / 政治 等）
  subjectLabel: string;
  content: string;
  // 知识图谱坐标（相对 0~1）
  x: number;
  y: number;
  // 关联知识点 id
  relatedIds: string[];
  // 所属章节/分组
  group: string;
}

// 卡片题型
export type CardType = "cloze" | "choice" | "flash";

// 8 种记忆方法
export type MemoryMethod =
  | "image"
  | "scene"
  | "associate"
  | "contrast"
  | "homophone"
  | "split"
  | "loci"
  | "feynman";

export interface Card {
  id: string;
  kpId: string;
  type: CardType;
  front: string;
  back: string;
  method: MemoryMethod;
  // 选择题选项
  options?: string[];
  answerIndex?: number;
  // 挖空题：被挖去的原文片段
  blank?: string;
}

// SM-2 调度信息
export interface Schedule {
  cardId: string;
  interval: number; // 天
  easeFactor: number; // 难度系数
  repetitions: number; // 连续正确次数
  nextReview: string; // ISO 日期
  lastReview: string | null;
  lastQuality: number | null; // 0-5
}

// 复习会话日志
export interface SessionLog {
  id: string;
  cardId: string;
  quality: number;
  timestamp: string;
}

// UI 四档评分映射到 SM-2 quality
export type Rating = "again" | "hard" | "good" | "easy";

export const RATING_TO_QUALITY: Record<Rating, number> = {
  again: 2,
  hard: 3,
  good: 4,
  easy: 5,
};

// 学科参数调制
export interface SubjectConfig {
  preset: SubjectPreset;
  initInterval: number;
  easeMin: number;
  easeMax: number;
  knowledgeTrait: string;
}

