import { useRef, useEffect, useState, useCallback } from "react";
import { useStore } from "@/store/useStore";
import { KnowledgePoint } from "@/lib/types";
import { masteryToLevel } from "@/lib/sm2";
import { X, Repeat, Link2, Lightbulb } from "lucide-react";
import { useNavigate } from "react-router-dom";

interface NodePos {
  kp: KnowledgePoint;
  x: number;
  y: number;
  mastery: number;
  level: 0 | 1 | 2 | 3;
}

const PADDING = 70;

export default function Graph() {
  const navigate = useNavigate();
  const knowledgePoints = useStore((s) => s.knowledgePoints);
  const getKpMastery = useStore((s) => s.getKpMastery);
  const [selected, setSelected] = useState<string | null>(null);
  const [hovered, setHovered] = useState<string | null>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const animRef = useRef<number>(0);
  const sizeRef = useRef({ w: 800, h: 560 });

  const nodes: NodePos[] = knowledgePoints.map((kp) => {
    const m = getKpMastery(kp.id);
    return { kp, x: 0, y: 0, mastery: m, level: masteryToLevel(m) };
  });

  const draw = useCallback(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;
    const { w, h } = sizeRef.current;
    const dpr = window.devicePixelRatio || 1;

    canvas.width = w * dpr;
    canvas.height = h * dpr;
    canvas.style.width = `${w}px`;
    canvas.style.height = `${h}px`;
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.clearRect(0, 0, w, h);

    // 计算节点像素坐标
    const innerW = w - PADDING * 2;
    const innerH = h - PADDING * 2;
    nodes.forEach((n) => {
      n.x = PADDING + n.kp.x * innerW;
      n.y = PADDING + n.kp.y * innerH;
    });

    const t = Date.now() / 1000;

    // 1. 绘制电线（关联连线）
    knowledgePoints.forEach((kp) => {
      kp.relatedIds.forEach((rid) => {
        const a = nodes.find((n) => n.kp.id === kp.id);
        const b = nodes.find((n) => n.kp.id === rid);
        if (!a || !b) return;
        const bothLevel = Math.max(a.level, b.level);
        const isHighlight =
          hovered === kp.id || hovered === rid || selected === kp.id || selected === rid;
        // 关联强度 → 线宽
        const lineWidth = 0.6 + bothLevel * 0.7 + (isHighlight ? 1.2 : 0);
        const grad = ctx.createLinearGradient(a.x, a.y, b.x, b.y);
        const alpha = isHighlight ? 0.85 : 0.25 + bothLevel * 0.1;
        grad.addColorStop(0, `rgba(95,184,201,${alpha})`);
        grad.addColorStop(0.5, `rgba(95,184,201,${alpha * 0.7})`);
        grad.addColorStop(1, `rgba(245,185,66,${alpha})`);
        ctx.strokeStyle = grad;
        ctx.lineWidth = lineWidth;
        ctx.beginPath();
        ctx.moveTo(a.x, a.y);
        ctx.lineTo(b.x, b.y);
        ctx.stroke();

        // 高亮时画电流流动小点
        if (isHighlight) {
          const flow = (t * 0.4) % 1;
          const px = a.x + (b.x - a.x) * flow;
          const py = a.y + (b.y - a.y) * flow;
          ctx.beginPath();
          ctx.arc(px, py, 2.5, 0, Math.PI * 2);
          ctx.fillStyle = "rgba(255,210,122,0.9)";
          ctx.shadowColor = "rgba(245,185,66,0.8)";
          ctx.shadowBlur = 8;
          ctx.fill();
          ctx.shadowBlur = 0;
        }
      });
    });

    // 2. 绘制灯泡节点
    nodes.forEach((n) => {
      const isSel = selected === n.kp.id;
      const isHov = hovered === n.kp.id;
      const breath = 1 + Math.sin(t * 1.5 + n.x * 0.01) * 0.08;
      const radius = (8 + n.level * 2.5) * (isHov || isSel ? 1.15 : 1);

      // 外辉光（掌握度越高辉光越大越亮）
      if (n.level >= 1) {
        const glowR = (18 + n.level * 10) * breath;
        const glowAlpha = 0.12 + n.level * 0.12 + (isHov ? 0.1 : 0);
        const rg = ctx.createRadialGradient(n.x, n.y, 0, n.x, n.y, glowR);
        rg.addColorStop(0, `rgba(255,210,122,${glowAlpha})`);
        rg.addColorStop(0.5, `rgba(245,185,66,${glowAlpha * 0.5})`);
        rg.addColorStop(1, "rgba(245,185,66,0)");
        ctx.fillStyle = rg;
        ctx.beginPath();
        ctx.arc(n.x, n.y, glowR, 0, Math.PI * 2);
        ctx.fill();
      }

      // 灯泡主体
      const bulbColor =
        n.level === 0 ? "rgba(139,147,167,0.35)" :
        n.level === 1 ? "rgba(245,185,66,0.55)" :
        n.level === 2 ? "rgba(245,185,66,0.85)" :
        "rgba(255,210,122,1)";
      ctx.beginPath();
      ctx.arc(n.x, n.y, radius, 0, Math.PI * 2);
      ctx.fillStyle = bulbColor;
      if (n.level >= 2) {
        ctx.shadowColor = "rgba(245,185,66,0.8)";
        ctx.shadowBlur = 12;
      }
      ctx.fill();
      ctx.shadowBlur = 0;

      // 选中/悬停描边
      if (isSel || isHov) {
        ctx.beginPath();
        ctx.arc(n.x, n.y, radius + 4, 0, Math.PI * 2);
        ctx.strokeStyle = isSel ? "rgba(255,210,122,0.9)" : "rgba(255,210,122,0.5)";
        ctx.lineWidth = 1.5;
        ctx.stroke();
      }

      // 灯泡底座小线
      ctx.strokeStyle = "rgba(95,184,201,0.6)";
      ctx.lineWidth = 1.2;
      ctx.beginPath();
      ctx.moveTo(n.x - 3, n.y + radius + 1);
      ctx.lineTo(n.x + 3, n.y + radius + 1);
      ctx.stroke();

      // 标签
      const showLabel = isSel || isHov || n.level >= 2;
      if (showLabel) {
        ctx.font = `${isHov || isSel ? "600 12px" : "500 11px"} "Noto Sans SC", sans-serif`;
        ctx.textAlign = "center";
        ctx.fillStyle = isSel ? "rgba(255,210,122,1)" : "rgba(232,230,225,0.85)";
        ctx.fillText(n.kp.title, n.x, n.y + radius + 16);
      }
    });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [knowledgePoints, hovered, selected, getKpMastery]);

  // 动画循环
  useEffect(() => {
    const loop = () => {
      draw();
      animRef.current = requestAnimationFrame(loop);
    };
    loop();
    return () => cancelAnimationFrame(animRef.current);
  }, [draw]);

  // 自适应尺寸
  useEffect(() => {
    function resize() {
      const el = containerRef.current;
      if (!el) return;
      sizeRef.current = { w: el.clientWidth, h: Math.max(480, el.clientHeight) };
    }
    resize();
    window.addEventListener("resize", resize);
    return () => window.removeEventListener("resize", resize);
  }, []);

  // 点击命中检测
  function handleMove(e: React.MouseEvent) {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const rect = canvas.getBoundingClientRect();
    const mx = e.clientX - rect.left;
    const my = e.clientY - rect.top;
    let hit: string | null = null;
    for (const n of nodes) {
      const dx = mx - n.x;
      const dy = my - n.y;
      if (Math.sqrt(dx * dx + dy * dy) < 16) {
        hit = n.kp.id;
        break;
      }
    }
    setHovered(hit);
    canvas.style.cursor = hit ? "pointer" : "default";
  }

  function handleClick(e: React.MouseEvent) {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const rect = canvas.getBoundingClientRect();
    const mx = e.clientX - rect.left;
    const my = e.clientY - rect.top;
    for (const n of nodes) {
      const dx = mx - n.x;
      const dy = my - n.y;
      if (Math.sqrt(dx * dx + dy * dy) < 16) {
        setSelected(n.kp.id);
        return;
      }
    }
    setSelected(null);
  }

  const selectedKp = knowledgePoints.find((k) => k.id === selected);
  const selectedMastery = selectedKp ? getKpMastery(selectedKp.id) : 0;

  return (
    <div className="animate-fade-up">
      <header className="mb-6">
        <p className="eyebrow mb-2">灯泡电线知识图谱</p>
        <h1 className="display text-3xl sm:text-4xl">
          你的知识，<span className="text-amber-glow">正在被点亮</span>
        </h1>
        <p className="mt-2 max-w-2xl text-sm leading-relaxed text-warm-muted">
          每个灯泡是一个知识点，亮度映射掌握度，电线粗细映射关联强度。
          点亮的灯泡越多，知识网络越明亮——就像神经元被逐个激活。
        </p>
      </header>

      <div className="grid gap-5 lg:grid-cols-[1fr_320px]">
        {/* 画布 */}
        <div ref={containerRef} className="glass-card relative h-[520px] overflow-hidden">
          <canvas
            ref={canvasRef}
            onMouseMove={handleMove}
            onMouseLeave={() => setHovered(null)}
            onClick={handleClick}
            className="block"
          />
          {/* 图例 */}
          <div className="absolute bottom-3 left-3 flex items-center gap-3 rounded-lg bg-ink-950/70 px-3 py-2 backdrop-blur">
            <LegendDot level={0} label="未学" />
            <LegendDot level={1} label="生疏" />
            <LegendDot level={2} label="熟悉" />
            <LegendDot level={3} label="熟练" />
          </div>
        </div>

        {/* 详情面板 */}
        <div className="space-y-4">
          {selectedKp ? (
            <div className="glass-card animate-fade-up p-5">
              <div className="mb-3 flex items-start justify-between">
                <div>
                  <p className="text-xs text-amber-glow/80">{selectedKp.subjectLabel} · {selectedKp.group}</p>
                  <h3 className="mt-1 font-serif text-lg font-bold text-warm-white">{selectedKp.title}</h3>
                </div>
                <button onClick={() => setSelected(null)} className="text-warm-faint hover:text-warm-white">
                  <X size={16} />
                </button>
              </div>

              <p className="mb-4 text-sm leading-relaxed text-warm-muted">{selectedKp.content}</p>

              {/* 掌握度 */}
              <div className="mb-4">
                <div className="mb-1.5 flex items-center justify-between text-xs">
                  <span className="text-warm-muted">掌握度</span>
                  <span className="font-mono text-amber-glow">{Math.round(selectedMastery * 100)}%</span>
                </div>
                <div className="h-2 overflow-hidden rounded-full bg-white/5">
                  <div
                    className="h-full rounded-full bg-gradient-to-r from-amber-dim to-amber-glow transition-all duration-700"
                    style={{ width: `${selectedMastery * 100}%` }}
                  />
                </div>
              </div>

              {/* 关联知识点 */}
              <div className="mb-4">
                <p className="mb-2 flex items-center gap-1.5 text-xs text-warm-muted">
                  <Link2 size={12} /> 关联知识点
                </p>
                <div className="flex flex-wrap gap-2">
                  {selectedKp.relatedIds.map((rid) => {
                    const r = knowledgePoints.find((k) => k.id === rid);
                    if (!r) return null;
                    return (
                      <button
                        key={rid}
                        onClick={() => setSelected(rid)}
                        className="rounded-full border border-teal-wire/30 bg-teal-wire/5 px-3 py-1 text-xs text-teal-wire transition-colors hover:bg-teal-wire/15"
                      >
                        {r.title}
                      </button>
                    );
                  })}
                  {selectedKp.relatedIds.length === 0 && (
                    <span className="text-xs text-warm-faint">暂无关联</span>
                  )}
                </div>
              </div>

              <button
                onClick={() => navigate("/review")}
                className="btn-ghost w-full"
              >
                <Repeat size={14} /> 去复习这个知识点
              </button>
            </div>
          ) : (
            <div className="glass-card flex flex-col items-center justify-center p-8 text-center">
              <div className="mb-3 grid h-12 w-12 place-items-center rounded-full bg-amber/10">
                <Lightbulb size={22} className="text-amber-glow animate-pulse-glow" />
              </div>
              <p className="text-sm font-medium text-warm-white">点击任一灯泡</p>
              <p className="mt-1 text-xs text-warm-muted">查看知识点详情与关联</p>
            </div>
          )}

          {/* 提示卡 */}
          <div className="glass-card p-4">
            <p className="text-xs leading-relaxed text-warm-muted">
              <span className="text-amber-glow">提示：</span>
              鼠标悬停可高亮灯泡与其关联电线，关联越强电线越粗。
              复习并评分后，灯泡亮度会实时更新。
            </p>
          </div>
        </div>
      </div>
    </div>
  );
}

function LegendDot({ level, label }: { level: 0 | 1 | 2 | 3; label: string }) {
  const opacity = [0.35, 0.55, 0.85, 1][level];
  return (
    <span className="flex items-center gap-1.5">
      <span
        className="inline-block h-2.5 w-2.5 rounded-full"
        style={{
          backgroundColor: level === 0 ? "rgba(139,147,167,0.6)" : `rgba(245,185,66,${opacity})`,
          boxShadow: level >= 2 ? "0 0 6px rgba(245,185,66,0.7)" : "none",
        }}
      />
      <span className="text-[10px] text-warm-muted">{label}</span>
    </span>
  );
}
