// SM-2 间隔重复算法 —— 真实实现（客户端运行）
// 参考：SuperMemo SM-2 算法，叠加学科参数调制与考前冲刺模式

import { Schedule, SubjectPreset, SUBJECT_CONFIGS, Rating, RATING_TO_QUALITY } from "./types";

// 生成今日日期（去掉时分秒，便于按天比较）
export function todayISO(): string {
  return new Date().toISOString().slice(0, 10);
}

export function addDays(iso: string, days: number): string {
  const d = new Date(iso + "T00:00:00");
  d.setDate(d.getDate() + days);
  return d.toISOString().slice(0, 10);
}

// 根据学科 preset 创建初始调度
export function createInitialSchedule(
  cardId: string,
  preset: SubjectPreset,
  sprintMode = false
): Schedule {
  const cfg = SUBJECT_CONFIGS[preset];
  const baseInterval = sprintMode ? Math.max(1, Math.round(cfg.initInterval * 0.5)) : cfg.initInterval;
  // 初始 EF 取范围中点
  const ease = +((cfg.easeMin + cfg.easeMax) / 2).toFixed(2);
  return {
    cardId,
    interval: baseInterval,
    easeFactor: ease,
    repetitions: 0,
    nextReview: addDays(todayISO(), baseInterval),
    lastReview: null,
    lastQuality: null,
  };
}

interface SM2Result {
  interval: number;
  easeFactor: number;
  repetitions: number;
  nextReview: string;
}

/**
 * SM-2 核心计算
 * @param schedule 当前调度信息
 * @param rating UI 四档评分
 * @param preset 学科 preset（用于参数调制）
 * @param sprintMode 是否考前冲刺（间隔 ×0.5）
 */
export function sm2(
  schedule: Schedule,
  rating: Rating,
  preset: SubjectPreset,
  sprintMode = false
): SM2Result {
  const q = RATING_TO_QUALITY[rating];
  let { interval, easeFactor: ef, repetitions } = schedule;

  if (q < 3) {
    // 答错：重置
    repetitions = 0;
    interval = SUBJECT_CONFIGS[preset].initInterval;
  } else {
    if (repetitions === 0) {
      interval = SUBJECT_CONFIGS[preset].initInterval === 1 ? 1 : 3;
    } else if (repetitions === 1) {
      interval = 6;
    } else {
      interval = Math.round(interval * ef);
    }
    repetitions += 1;
  }

  // 更新难度系数
  ef = ef + (0.1 - (5 - q) * (0.08 + (5 - q) * 0.02));
  // 学科参数调制：限制 EF 在该学科范围内
  const cfg = SUBJECT_CONFIGS[preset];
  ef = Math.min(cfg.easeMax, Math.max(cfg.easeMin, ef));
  ef = +ef.toFixed(2);

  // 间隔下限保护
  if (interval < 1) interval = 1;

  // 考前冲刺模式：间隔缩短 50%
  if (sprintMode) interval = Math.max(1, Math.round(interval * 0.5));

  return {
    interval,
    easeFactor: ef,
    repetitions,
    nextReview: addDays(todayISO(), interval),
  };
}

// 预测某评分下的下次间隔（用于评分条悬停提示，不写入状态）
export function previewInterval(
  schedule: Schedule,
  rating: Rating,
  preset: SubjectPreset,
  sprintMode = false
): number {
  return sm2(schedule, rating, preset, sprintMode).interval;
}

// 计算知识点的掌握度（0~1），用于灯泡亮度
export function computeMastery(schedule: Schedule): number {
  // 最近一次答错 → 掌握度封顶 0.3
  if (schedule.lastQuality !== null && schedule.lastQuality < 3) {
    return 0.25;
  }
  const repPart = Math.min(1, schedule.repetitions / 5) * 0.55;
  const intPart = Math.min(1, schedule.interval / 30) * 0.45;
  return Math.max(0.05, Math.min(1, repPart + intPart));
}

// 把掌握度转为灯泡亮度等级（0~3）
export function masteryToLevel(mastery: number): 0 | 1 | 2 | 3 {
  if (mastery < 0.2) return 0;
  if (mastery < 0.45) return 1;
  if (mastery < 0.75) return 2;
  return 3;
}

// 人类可读的间隔描述
export function formatInterval(days: number): string {
  if (days < 1) return "今日内";
  if (days === 1) return "1 天后";
  if (days < 30) return `${days} 天后`;
  if (days < 365) return `${Math.round(days / 30)} 个月后`;
  return `${(days / 365).toFixed(1)} 年后`;
}
