import { useState } from "react";
import { useStore } from "@/store/useStore";
import { VERIFY_QUESTIONS } from "@/lib/seedData";
import {
  ShieldCheck, ShieldAlert, Eye, Check, X, RotateCcw,
  AlertTriangle, Search, Lightbulb, Wrench, Target, ArrowRight, type LucideIcon,
} from "lucide-react";
import { cn } from "@/lib/utils";

type Step = "intro" | "thinking" | "reveal" | "review" | "summary";

const REVIEW_STEPS = [
  { icon: AlertTriangle, title: "明确问题", desc: "你卡在了哪里？是概念混淆、推导断裂，还是场景迁移失败？" },
  { icon: Search, title: "本质溯源", desc: "回到知识点的定义与原理，找到理解断点的根源。" },
  { icon: Lightbulb, title: "生成方案", desc: "AI 给出 2-3 种补救方案：换记忆方法、补前置知识、做应用练习。" },
  { icon: Wrench, title: "多方案适配", desc: "根据你的学情与偏好，挑选最适合的一种方案落地。" },
  { icon: Target, title: "执行落地", desc: "生成针对性的新卡片与练习，纳入下一轮 SM-2 复习。" },
];

export default function Verify() {
  const knowledgePoints = useStore((s) => s.knowledgePoints);
  const [qi, setQi] = useState(0);
  const [step, setStep] = useState<Step>("intro");
  const [results, setResults] = useState<{ pass: boolean }[]>([]);

  const question = VERIFY_QUESTIONS[qi];
  const kp = knowledgePoints.find((k) => k.id === question?.kpId);
  const isLast = qi >= VERIFY_QUESTIONS.length - 1;

  function startVerify() {
    setStep("thinking");
  }

  function reveal() {
    setStep("reveal");
  }

  function judge(pass: boolean) {
    setResults((r) => [...r, { pass }]);
    if (!pass) {
      setStep("review");
    } else {
      next();
    }
  }

  function finishReview() {
    next();
  }

  function next() {
    if (isLast) {
      setStep("summary");
    } else {
      setQi((i) => i + 1);
      setStep("thinking");
    }
  }

  function reset() {
    setQi(0);
    setStep("intro");
    setResults([]);
  }

  // ===== 介绍页 =====
  if (step === "intro") {
    return (
      <div className="animate-fade-up mx-auto max-w-2xl pt-6">
        <div className="mb-6 grid h-16 w-16 place-items-center rounded-2xl bg-amber/10 shadow-glow">
          <ShieldCheck size={32} className="text-amber-glow" />
        </div>
        <p className="eyebrow mb-2">深度校验机制</p>
        <h1 className="display text-3xl sm:text-4xl">
          你以为会了，<span className="text-amber-glow">真的会了吗？</span>
        </h1>
        <p className="mt-4 leading-relaxed text-warm-muted">
          深度校验会换一个角度，抽考你已标记「熟练」的知识点。
          它排查的是最隐蔽的痛点——<span className="text-amber-glow">能力错觉</span>：
          记得住定义，但换个问法就用不出来。
        </p>

        <div className="mt-6 grid gap-3 sm:grid-cols-3">
          <InfoCard icon={Eye} title="换角度抽考" desc="不是原题重现，而是新情境提问" />
          <InfoCard icon={ShieldAlert} title="排查错觉" desc="识别「以为自己会了」的盲区" />
          <InfoCard icon={RotateCcw} title="结构化复盘" desc="失败即触发五步补救流程" />
        </div>

        <div className="mt-8 rounded-xl border border-teal-wire/20 bg-teal-wire/5 p-4">
          <p className="text-sm leading-relaxed text-warm-muted">
            <span className="text-teal-wire">本次校验：</span>
            将抽考 {VERIFY_QUESTIONS.length} 个你已「熟练」的知识点。
            请诚实地自评——校验的目的是发现问题，不是证明自己。
          </p>
        </div>

        <button onClick={startVerify} className="btn-glow mt-8 mx-auto flex">
          <ShieldCheck size={18} /> 开始深度校验
        </button>
      </div>
    );
  }

  // ===== 总结页 =====
  if (step === "summary") {
    const passed = results.filter((r) => r.pass).length;
    const failed = results.length - passed;
    return (
      <div className="animate-fade-up mx-auto max-w-lg pt-6 text-center">
        <div className={cn(
          "mx-auto mb-6 grid h-20 w-20 place-items-center rounded-full",
          failed === 0 ? "bg-emerald-500/15" : "bg-amber/10 shadow-glow"
        )}>
          {failed === 0
            ? <Check size={36} className="text-emerald-300" />
            : <ShieldAlert size={36} className="text-amber-glow" />}
        </div>
        <h1 className="display text-3xl">校验完成</h1>
        <p className="mt-2 text-sm text-warm-muted">
          {failed === 0
            ? "全部通过——你的「熟练」名副其实。"
            : "发现能力错觉——这正是考前最该补的盲区。"}
        </p>

        <div className="mt-8 glass-card p-6">
          <div className="grid grid-cols-2 gap-4">
            <div className="rounded-xl border border-emerald-400/20 bg-emerald-400/5 p-4">
              <div className="font-serif text-3xl font-black text-emerald-300">{passed}</div>
              <div className="mt-1 text-xs text-warm-muted">真正掌握</div>
            </div>
            <div className="rounded-xl border border-rose-400/20 bg-rose-400/5 p-4">
              <div className="font-serif text-3xl font-black text-rose-300">{failed}</div>
              <div className="mt-1 text-xs text-warm-muted">能力错觉</div>
            </div>
          </div>
        </div>

        <button onClick={reset} className="btn-ghost mt-8 mx-auto flex">
          <RotateCcw size={16} /> 重新校验
        </button>
      </div>
    );
  }

  // ===== 思考 / 揭晓 / 复盘 =====
  return (
    <div className="animate-fade-up mx-auto max-w-2xl">
      {/* 进度 */}
      <div className="mb-6 flex items-center justify-between">
        <span className="text-xs text-warm-muted">
          深度校验 · 第 {qi + 1} / {VERIFY_QUESTIONS.length} 题
        </span>
        <div className="flex gap-1">
          {results.map((r, i) => (
            <span
              key={i}
              className={cn("h-1.5 w-6 rounded-full", r.pass ? "bg-emerald-400" : "bg-rose-400")}
            />
          ))}
          {Array.from({ length: VERIFY_QUESTIONS.length - results.length }).map((_, i) => (
            <span key={`p-${i}`} className="h-1.5 w-6 rounded-full bg-white/10" />
          ))}
        </div>
      </div>

      {/* 抽考卡 */}
      {step !== "review" && (
        <div className="glass-card p-7">
          <div className="mb-3 flex items-center gap-2">
            <span className="rounded-md bg-amber/10 px-2.5 py-1 text-xs text-amber-glow">
              {kp?.subjectLabel} · {kp?.title}
            </span>
            <span className="rounded-md bg-white/5 px-2.5 py-1 text-xs text-warm-muted">
              换角度抽考
            </span>
          </div>

          <div className="mb-2 flex items-center gap-2 text-xs text-amber-glow/80">
            <ShieldAlert size={14} />
            <span>不再是原题，而是新情境下的应用</span>
          </div>

          <p className="font-serif text-xl leading-relaxed text-warm-white">{question.question}</p>

          {step === "thinking" && (
            <>
              <p className="mt-4 text-sm text-warm-muted">{question.hint}</p>
              <button onClick={reveal} className="btn-glow mt-6 flex w-full max-w-xs mx-auto">
                <Eye size={18} /> 想好了，看参考答案
              </button>
            </>
          )}

          {step === "reveal" && (
            <>
              <div className="mt-5 rounded-xl border border-amber/15 bg-amber/[0.04] p-5">
                <p className="mb-2 text-xs font-medium uppercase tracking-wider text-amber-glow/80">
                  参考答案要点
                </p>
                <ul className="space-y-1.5">
                  {question.keyPoints.map((kp2, i) => (
                    <li key={i} className="flex items-start gap-2 text-sm text-warm-white">
                      <Check size={14} className="mt-1 shrink-0 text-amber-glow" />
                      {kp2}
                    </li>
                  ))}
                </ul>
              </div>

              <p className="mt-5 text-center text-xs text-warm-muted">
                对照参考要点，诚实自评：你刚才真的答上来了吗？
              </p>

              <div className="mt-4 grid grid-cols-2 gap-3">
                <button
                  onClick={() => judge(false)}
                  className="flex flex-col items-center gap-1 rounded-xl border border-rose-400/40 bg-rose-400/5 py-3 text-rose-300 transition-all hover:bg-rose-400/10"
                >
                  <X size={18} />
                  <span className="text-sm font-medium">没答上来</span>
                  <span className="text-[10px] opacity-70">触发结构化复盘</span>
                </button>
                <button
                  onClick={() => judge(true)}
                  className="flex flex-col items-center gap-1 rounded-xl border border-emerald-400/40 bg-emerald-400/5 py-3 text-emerald-300 transition-all hover:bg-emerald-400/10"
                >
                  <Check size={18} />
                  <span className="text-sm font-medium">答上来了</span>
                  <span className="text-[10px] opacity-70">真正掌握</span>
                </button>
              </div>
            </>
          )}
        </div>
      )}

      {/* 五步结构化复盘 */}
      {step === "review" && (
        <div className="animate-fade-up">
          <div className="mb-5 flex items-center gap-3">
            <div className="grid h-11 w-11 place-items-center rounded-xl bg-rose-400/15">
              <ShieldAlert size={22} className="text-rose-300" />
            </div>
            <div>
              <p className="text-xs uppercase tracking-widest text-rose-300/80">能力错觉已识别</p>
              <h2 className="display text-xl">五步结构化复盘</h2>
            </div>
          </div>

          <div className="space-y-2.5">
            {REVIEW_STEPS.map((s, i) => (
              <div
                key={i}
                className="glass-card flex items-start gap-4 p-4"
                style={{ animation: `fadeUp 0.4s ease-out ${i * 0.08}s both` }}
              >
                <div className="grid h-9 w-9 shrink-0 place-items-center rounded-lg bg-amber/10 text-amber-glow">
                  <s.icon size={16} />
                </div>
                <div className="flex-1">
                  <div className="flex items-center gap-2">
                    <span className="font-mono text-[10px] text-warm-faint">0{i + 1}</span>
                    <span className="text-sm font-medium text-warm-white">{s.title}</span>
                  </div>
                  <p className="mt-1 text-xs leading-relaxed text-warm-muted">{s.desc}</p>
                </div>
              </div>
            ))}
          </div>

          <div className="mt-5 rounded-xl border border-teal-wire/20 bg-teal-wire/5 p-4">
            <p className="text-sm leading-relaxed text-warm-muted">
              <span className="text-teal-wire">已为你生成：</span>
              针对「{kp?.title}」的 2 张新卡片 + 1 道应用练习题，
              已纳入下一轮 SM-2 复习。下次它会更早、更频繁地回到你面前。
            </p>
          </div>

          <button onClick={finishReview} className="btn-glow mt-6 flex w-full max-w-xs mx-auto">
            {isLast ? "查看校验结果" : "继续下一题"}
            <ArrowRight size={18} />
          </button>
        </div>
      )}
    </div>
  );
}

function InfoCard({
  icon: Icon, title, desc,
}: { icon: LucideIcon; title: string; desc: string }) {
  return (
    <div className="glass-card p-4">
      <div className="mb-2 grid h-9 w-9 place-items-center rounded-lg bg-amber/10 text-amber-glow">
        <Icon size={16} />
      </div>
      <p className="text-sm font-medium text-warm-white">{title}</p>
      <p className="mt-0.5 text-xs leading-relaxed text-warm-muted">{desc}</p>
    </div>
  );
}
