// 进度环 —— 用于掌握度展示
interface Props {
  value: number; // 0~1
  size?: number;
  stroke?: number;
  label?: string;
  sublabel?: string;
  glow?: boolean;
}

export default function ProgressRing({
  value,
  size = 132,
  stroke = 10,
  label,
  sublabel,
  glow = true,
}: Props) {
  const r = (size - stroke) / 2;
  const c = 2 * Math.PI * r;
  const pct = Math.max(0, Math.min(1, value));
  const offset = c * (1 - pct);

  return (
    <div className="relative inline-flex items-center justify-center" style={{ width: size, height: size }}>
      <svg width={size} height={size} className="-rotate-90">
        <defs>
          <linearGradient id="ring-grad" x1="0%" y1="0%" x2="100%" y2="100%">
            <stop offset="0%" stopColor="#ffd27a" />
            <stop offset="100%" stopColor="#f5b942" />
          </linearGradient>
          <filter id="ring-glow">
            <feGaussianBlur stdDeviation="3" result="b" />
            <feMerge>
              <feMergeNode in="b" />
              <feMergeNode in="SourceGraphic" />
            </feMerge>
          </filter>
        </defs>
        <circle
          cx={size / 2} cy={size / 2} r={r}
          fill="none" stroke="rgba(139,147,167,0.15)" strokeWidth={stroke}
        />
        <circle
          cx={size / 2} cy={size / 2} r={r}
          fill="none" stroke="url(#ring-grad)" strokeWidth={stroke}
          strokeLinecap="round"
          strokeDasharray={c} strokeDashoffset={offset}
          filter={glow ? "url(#ring-glow)" : undefined}
          style={{ transition: "stroke-dashoffset 0.8s cubic-bezier(0.4,0,0.2,1)" }}
        />
      </svg>
      <div className="absolute inset-0 flex flex-col items-center justify-center">
        {label && (
          <span className="font-serif text-3xl font-black text-warm-white">
            {label}
          </span>
        )}
        {sublabel && (
          <span className="mt-0.5 text-xs text-warm-muted">{sublabel}</span>
        )}
      </div>
    </div>
  );
}
