import { NavLink, useLocation } from "react-router-dom";
import {
  LayoutDashboard, Repeat, Sparkles, Network, Lightbulb,
  ShieldCheck, Menu, X,
  type LucideIcon,
} from "lucide-react";
import { useState } from "react";
import { cn } from "@/lib/utils";

const NAV = [
  { to: "/", label: "今日", icon: LayoutDashboard, end: true },
  { to: "/review", label: "复习", icon: Repeat, end: false },
  { to: "/generate", label: "AI 生成", icon: Sparkles, end: false },
  { to: "/graph", label: "知识图谱", icon: Network, end: false },
  { to: "/methods", label: "记忆方法", icon: Lightbulb, end: false },
  { to: "/verify", label: "深度校验", icon: ShieldCheck, end: false },
];

export default function Layout({ children }: { children: React.ReactNode }) {
  const [open, setOpen] = useState(false);
  const loc = useLocation();

  return (
    <div className="min-h-screen lg:flex">
      {/* 桌面侧边栏 */}
      <aside className="fixed inset-y-0 left-0 z-40 hidden w-64 flex-col border-r border-white/5 bg-ink-950/60 backdrop-blur-xl lg:flex">
        <Brand />
        <nav className="mt-4 flex flex-1 flex-col gap-1 px-3">
          {NAV.map((item) => (
            <NavItem key={item.to} {...item} active={isActive(item.to, loc.pathname, item.end)} />
          ))}
        </nav>
        <FooterNote />
      </aside>

      {/* 移动端顶栏 */}
      <header className="sticky top-0 z-40 flex items-center justify-between border-b border-white/5 bg-ink-950/80 px-4 py-3 backdrop-blur-xl lg:hidden">
        <Brand compact />
        <button
          onClick={() => setOpen((v) => !v)}
          className="rounded-lg border border-white/10 p-2 text-warm-muted"
          aria-label="菜单"
        >
          {open ? <X size={20} /> : <Menu size={20} />}
        </button>
      </header>

      {/* 移动端抽屉菜单 */}
      {open && (
        <div className="fixed inset-0 z-30 lg:hidden" onClick={() => setOpen(false)}>
          <div className="absolute inset-0 bg-black/60" />
          <nav className="absolute right-0 top-0 h-full w-64 border-l border-white/5 bg-ink-900 p-4 pt-20">
            <div className="flex flex-col gap-1">
              {NAV.map((item) => (
                <NavItem
                  key={item.to}
                  {...item}
                  active={isActive(item.to, loc.pathname, item.end)}
                  onClick={() => setOpen(false)}
                />
              ))}
            </div>
          </nav>
        </div>
      )}

      {/* 主内容区 */}
      <main className="flex-1 lg:ml-64">
        <div className="mx-auto max-w-6xl px-4 py-8 sm:px-6 lg:px-10 lg:py-12">
          {children}
        </div>
      </main>
    </div>
  );
}

function Brand({ compact = false }: { compact?: boolean }) {
  return (
    <div className={cn("flex items-center gap-3", compact ? "" : "px-5 pt-6")}>
      <div className="relative grid h-10 w-10 place-items-center rounded-xl bg-gradient-to-br from-amber-glow to-amber-dim shadow-glow-sm">
        <Lightbulb size={20} className="text-ink-950" strokeWidth={2.5} />
      </div>
      <div>
        <div className="font-serif text-lg font-black tracking-wide text-warm-white">闪记</div>
        <div className="text-[10px] uppercase tracking-[0.18em] text-warm-faint">AI Memory</div>
      </div>
    </div>
  );
}

function NavItem({
  to, label, icon: Icon, active, end, onClick,
}: {
  to: string; label: string; icon: LucideIcon;
  active: boolean; end: boolean; onClick?: () => void;
}) {
  return (
    <NavLink
      to={to}
      end={end}
      onClick={onClick}
      className={cn(
        "group flex items-center gap-3 rounded-xl px-4 py-2.5 text-sm transition-all duration-200",
        active
          ? "bg-amber/10 text-amber-glow shadow-glow-sm"
          : "text-warm-muted hover:bg-white/5 hover:text-warm-white"
      )}
    >
      <Icon size={18} />
      <span className="font-medium">{label}</span>
      {active && <span className="ml-auto h-1.5 w-1.5 rounded-full bg-amber-glow animate-pulse-glow" />}
    </NavLink>
  );
}

function FooterNote() {
  return (
    <div className="px-5 py-5 text-[11px] leading-relaxed text-warm-faint">
      <p className="mb-1">TRAE AI 创造力大赛</p>
      <p>学习工作赛道 · 可交互 Demo</p>
    </div>
  );
}

function isActive(to: string, pathname: string, end: boolean): boolean {
  return end ? pathname === to : pathname.startsWith(to);
}
