// 灯泡图标组件 —— 知识点掌握度可视化
// level: 0=未点亮 1=微光 2=半亮 3=全亮
interface Props {
  level: 0 | 1 | 2 | 3;
  size?: number;
  animate?: boolean;
}

const LEVEL_OPACITY: Record<number, number> = { 0: 0.25, 1: 0.5, 2: 0.78, 3: 1 };
const LEVEL_GLOW: Record<number, string> = {
  0: "rgba(139,147,167,0.2)",
  1: "rgba(245,185,66,0.3)",
  2: "rgba(245,185,66,0.55)",
  3: "rgba(255,210,122,0.85)",
};

export default function BulbIcon({ level, size = 28, animate = false }: Props) {
  const opacity = LEVEL_OPACITY[level];
  const glow = LEVEL_GLOW[level];
  const gid = `bulb-grad-${level}`;
  const fid = `bulb-blur-${level}`;

  return (
    <svg width={size} height={size} viewBox="0 0 32 32" className={animate ? "animate-pulse-glow" : ""}>
      <defs>
        <radialGradient id={gid} cx="50%" cy="38%" r="60%">
          <stop offset="0%" stopColor="#ffd27a" />
          <stop offset="55%" stopColor="#f5b942" />
          <stop offset="100%" stopColor="#b8852a" />
        </radialGradient>
        <filter id={fid} x="-50%" y="-50%" width="200%" height="200%">
          <feGaussianBlur stdDeviation={level >= 2 ? 1.6 : 0.8} />
        </filter>
      </defs>
      {/* 外辉光 */}
      {level >= 1 && (
        <circle cx="16" cy="13" r="11" fill={glow} filter={`url(#${fid})`} opacity={opacity * 0.7} />
      )}
      {/* 灯泡主体 */}
      <path
        d="M16 3a9 9 0 0 0-5.6 16c.9.7 1.6 1.6 1.6 2.7v.3h8v-.3c0-1.1.7-2 1.6-2.7A9 9 0 0 0 16 3z"
        fill={`url(#${gid})`}
        opacity={opacity}
      />
      {/* 灯丝 */}
      {level >= 2 && (
        <path d="M13 12c1-2 5-2 6 0" fill="none" stroke="#fff7e0" strokeWidth="0.8" opacity="0.8" />
      )}
      {/* 螺纹底座 */}
      <rect x="12" y="23" width="8" height="2" rx="1" fill="#5fb8c9" opacity="0.9" />
      <rect x="12.5" y="26" width="7" height="2" rx="1" fill="#3a7a86" />
      <path d="M14 29h4" stroke="#5fb8c9" strokeWidth="1.5" strokeLinecap="round" />
    </svg>
  );
}
