// 闪记全局状态 —— Zustand + persist(localStorage)
import { create } from "zustand";
import { persist } from "zustand/middleware";
import {
  KnowledgePoint, Card, Schedule, SessionLog, Rating, SubjectPreset,
} from "@/lib/types";
import { SEED_KNOWLEDGE_POINTS, SEED_CARDS } from "@/lib/seedData";
import {
  createInitialSchedule, sm2, computeMastery, todayISO,
} from "@/lib/sm2";

interface StoreState {
  knowledgePoints: KnowledgePoint[];
  cards: Card[];
  schedules: Record<string, Schedule>; // cardId -> schedule
  logs: SessionLog[];
  streak: number;
  lastStudyDay: string | null;
  sprintMode: boolean;
  // 是否已初始化种子数据
  seeded: boolean;

  // actions
  rateCard: (cardId: string, rating: Rating) => void;
  getDueCards: () => Card[];
  getCardSchedule: (cardId: string) => Schedule;
  getKpMastery: (kpId: string) => number;
  getOverallMastery: () => number;
  getSubjectMastery: (subjectLabel: string) => number;
  toggleSprint: () => void;
  resetAll: () => void;
  addGeneratedCards: (cards: Card[]) => void;
}

// 为所有种子卡片生成初始调度（首次进入即有一部分今日待复习）
function buildSeedSchedules(): Record<string, Schedule> {
  const map: Record<string, Schedule> = {};
  SEED_CARDS.forEach((c, i) => {
    const preset: SubjectPreset = c.kpId.includes("history") || c.kpId.includes("pol") ? "文科类"
      : c.kpId.includes("eng") ? "语言类"
      : c.kpId.includes("math") || c.kpId.includes("phys") ? "理科公式"
      : "理科概念";
    const s = createInitialSchedule(c.id, preset);
    // 让前 60% 的卡片今天到期，其余分布在未来
    if (i < Math.floor(SEED_CARDS.length * 0.6)) {
      s.nextReview = todayISO();
    }
    map[c.id] = s;
  });
  return map;
}

export const useStore = create<StoreState>()(
  persist(
    (set, get) => ({
      knowledgePoints: SEED_KNOWLEDGE_POINTS,
      cards: SEED_CARDS,
      schedules: buildSeedSchedules(),
      logs: [],
      streak: 3,
      lastStudyDay: null,
      sprintMode: false,
      seeded: true,

      rateCard: (cardId, rating) => {
        const state = get();
        const card = state.cards.find((c) => c.id === cardId);
        if (!card) return;
        const kp = state.knowledgePoints.find((k) => k.id === card.kpId);
        const preset: SubjectPreset = kp?.preset ?? "文科类";
        const old = state.schedules[cardId];
        if (!old) return;
        const r = sm2(old, rating, preset, state.sprintMode);
        const newSchedule: Schedule = {
          ...old,
          interval: r.interval,
          easeFactor: r.easeFactor,
          repetitions: r.repetitions,
          nextReview: r.nextReview,
          lastReview: todayISO(),
          lastQuality: rating === "again" ? 2 : rating === "hard" ? 3 : rating === "good" ? 4 : 5,
        };
        const log: SessionLog = {
          id: `log-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
          cardId,
          quality: newSchedule.lastQuality!,
          timestamp: new Date().toISOString(),
        };
        // 更新连续打卡
        const today = todayISO();
        let streak = state.streak;
        if (state.lastStudyDay !== today) {
          // 若上次是昨天，streak +1；否则重置为 1
          const yesterday = new Date();
          yesterday.setDate(yesterday.getDate() - 1);
          streak = state.lastStudyDay === yesterday.toISOString().slice(0, 10)
            ? state.streak + 1
            : 1;
        }
        set({
          schedules: { ...state.schedules, [cardId]: newSchedule },
          logs: [...state.logs, log],
          lastStudyDay: today,
          streak,
        });
      },

      getDueCards: () => {
        const { cards, schedules } = get();
        const today = todayISO();
        return cards.filter((c) => {
          const s = schedules[c.id];
          return s && s.nextReview <= today;
        });
      },

      getCardSchedule: (cardId) => get().schedules[cardId] ?? createInitialSchedule(cardId, "文科类"),

      getKpMastery: (kpId) => {
        const { cards, schedules } = get();
        const kpCards = cards.filter((c) => c.kpId === kpId);
        if (kpCards.length === 0) return 0;
        const sum = kpCards.reduce((acc, c) => {
          const s = schedules[c.id];
          return acc + (s ? computeMastery(s) : 0);
        }, 0);
        return sum / kpCards.length;
      },

      getOverallMastery: () => {
        const { knowledgePoints, getKpMastery } = get();
        if (knowledgePoints.length === 0) return 0;
        const sum = knowledgePoints.reduce((acc, kp) => acc + getKpMastery(kp.id), 0);
        return sum / knowledgePoints.length;
      },

      getSubjectMastery: (subjectLabel) => {
        const { knowledgePoints, getKpMastery } = get();
        const kps = knowledgePoints.filter((k) => k.subjectLabel === subjectLabel);
        if (kps.length === 0) return 0;
        return kps.reduce((acc, kp) => acc + getKpMastery(kp.id), 0) / kps.length;
      },

      toggleSprint: () => set((s) => ({ sprintMode: !s.sprintMode })),

      addGeneratedCards: (newCards) => set((s) => {
        const newSchedules = { ...s.schedules };
        newCards.forEach((c) => {
          // 找到该卡片所属知识点 preset
          const kp = s.knowledgePoints.find((k) => k.id === c.kpId);
          newSchedules[c.id] = createInitialSchedule(c.id, kp?.preset ?? "文科类", s.sprintMode);
        });
        return { cards: [...s.cards, ...newCards], schedules: newSchedules };
      }),

      resetAll: () => set({
        knowledgePoints: SEED_KNOWLEDGE_POINTS,
        cards: SEED_CARDS,
        schedules: buildSeedSchedules(),
        logs: [],
        streak: 3,
        lastStudyDay: null,
        sprintMode: false,
        seeded: true,
      }),
    }),
    {
      name: "shanji-store-v1",
    }
  )
);
