import { useNavigate } from "react-router-dom";
import { useMemo } from "react";
import { useStore } from "@/store/useStore";
import ProgressRing from "@/components/ProgressRing";
import BulbIcon from "@/components/BulbIcon";
import { masteryToLevel } from "@/lib/sm2";
import {
  Repeat, Flame, Sparkles, Network, ChevronRight,
  TrendingUp, Clock, Zap, type LucideIcon,
} from "lucide-react";

const SUBJECTS = ["历史", "化学", "英语", "数学", "政治", "物理", "生物"];

export default function Home() {
  const navigate = useNavigate();
  const streak = useStore((s) => s.streak);
  const sprintMode = useStore((s) => s.sprintMode);
  const logs = useStore((s) => s.logs);
  const knowledgePoints = useStore((s) => s.knowledgePoints);
  const cards = useStore((s) => s.cards);
  const schedules = useStore((s) => s.schedules);
  const getDueCards = useStore((s) => s.getDueCards);
  const getOverallMastery = useStore((s) => s.getOverallMastery);
  const getSubjectMastery = useStore((s) => s.getSubjectMastery);

  const dueCards = useMemo(() => getDueCards(), [getDueCards, cards, schedules]);
  const overall = useMemo(() => getOverallMastery(), [getOverallMastery, cards, schedules]);

  const todayReviewed = logs.filter((l) => l.timestamp.slice(0, 10) === new Date().toISOString().slice(0, 10)).length;
  const greeting = getGreeting();

  return (
    <div className="animate-fade-up">
      {/* 顶部问候 */}
      <div className="mb-8 flex flex-wrap items-end justify-between gap-4">
        <div>
          <p className="eyebrow mb-2">{formatDate()}</p>
          <h1 className="display text-3xl sm:text-4xl">
            {greeting}，<span className="text-amber-glow">让知识被点亮</span>
          </h1>
          <p className="mt-2 text-sm text-warm-muted">
            今日有 <span className="font-semibold text-amber-glow">{dueCards.length}</span> 张卡片等待复习
          </p>
        </div>
        <div className="flex items-center gap-2 rounded-full border border-amber/20 bg-amber/5 px-4 py-2">
          <Flame size={18} className="text-amber-glow" />
          <span className="text-sm text-warm-white">连续 <b className="text-amber-glow">{streak}</b> 天</span>
        </div>
      </div>

      {/* 主任务卡 + 掌握度 */}
      <div className="grid gap-5 lg:grid-cols-3">
        {/* 今日任务大卡 */}
        <div className="glass-card relative overflow-hidden p-6 lg:col-span-2">
          <div className="pointer-events-none absolute -right-10 -top-10 h-40 w-40 rounded-full bg-amber/10 blur-3xl" />
          <div className="relative flex flex-col gap-6 sm:flex-row sm:items-center sm:justify-between">
            <div>
              <p className="eyebrow mb-3">今日任务</p>
              <div className="flex items-baseline gap-3">
                <span className="font-serif text-6xl font-black text-warm-white">{dueCards.length}</span>
                <span className="text-warm-muted">张待复习</span>
              </div>
              <p className="mt-3 max-w-sm text-sm leading-relaxed text-warm-muted">
                {dueCards.length > 0
                  ? "SM-2 算法已为你挑出今天最该复习的卡片。集中精力攻克它们，比盲目翻书高效得多。"
                  : "今天的复习任务已全部完成。去生成新卡片，或体验深度校验吧。"}
              </p>
              <div className="mt-5 flex flex-wrap gap-3">
                <button
                  onClick={() => navigate("/review")}
                  className="btn-glow"
                  disabled={dueCards.length === 0}
                >
                  <Repeat size={18} /> 开始复习
                </button>
                <button onClick={() => navigate("/generate")} className="btn-ghost">
                  <Sparkles size={16} /> AI 生成卡片
                </button>
              </div>
            </div>
            <ProgressRing
              value={dueCards.length > 0 ? todayReviewed / (todayReviewed + dueCards.length) : 1}
              label={`${Math.round(dueCards.length > 0 ? (todayReviewed / (todayReviewed + dueCards.length)) * 100 : 100)}%`}
              sublabel="今日进度"
            />
          </div>
        </div>

        {/* 掌握度总览 */}
        <div className="glass-card flex flex-col items-center justify-center p-6">
          <p className="eyebrow mb-4">总体掌握度</p>
          <ProgressRing
            value={overall}
            label={`${Math.round(overall * 100)}%`}
            sublabel="所有知识点"
          />
          <div className="mt-4 flex items-center gap-4 text-xs text-warm-muted">
            <span className="flex items-center gap-1.5"><BulbIcon level={3} size={16} /> 熟练</span>
            <span className="flex items-center gap-1.5"><BulbIcon level={1} size={16} /> 生疏</span>
          </div>
        </div>
      </div>

      {/* 快捷入口 */}
      <div className="mt-5 grid gap-4 sm:grid-cols-3">
        <QuickCard
          icon={Network} title="知识图谱"
          desc="灯泡亮度映射掌握度，电线粗细映射关联强度"
          onClick={() => navigate("/graph")}
        />
        <QuickCard
          icon={Sparkles} title="8 种记忆方法"
          desc="同一知识点，用不同科学方法呈现"
          onClick={() => navigate("/methods")}
        />
        <QuickCard
          icon={Zap} title="深度校验"
          desc="换角度抽考，排查「能力错觉」"
          onClick={() => navigate("/verify")}
        />
      </div>

      {/* 学科概览 */}
      <div className="mt-8">
        <div className="mb-4 flex items-center justify-between">
          <h2 className="display text-xl">学科掌握度</h2>
          <div className="flex items-center gap-2 text-xs text-warm-muted">
            <TrendingUp size={14} /> 共 {knowledgePoints.length} 个知识点
          </div>
        </div>
        <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">
          {SUBJECTS.map((subj) => {
            const m = getSubjectMastery(subj);
            return <SubjectCard key={subj} subject={subj} mastery={m} />;
          })}
        </div>
      </div>

      {/* 考前冲刺 */}
      <div className="mt-8 flex flex-wrap items-center justify-between gap-4 rounded-2xl border border-teal-wire/20 bg-teal-wire/5 p-5">
        <div className="flex items-center gap-3">
          <div className="grid h-10 w-10 place-items-center rounded-xl bg-teal-wire/15">
            <Clock size={18} className="text-teal-wire" />
          </div>
          <div>
            <p className="text-sm font-medium text-warm-white">考前冲刺模式</p>
            <p className="text-xs text-warm-muted">开启后所有复习间隔缩短 50%，适合考前 1-2 周</p>
          </div>
        </div>
        <SprintToggle />
      </div>
    </div>
  );
}

function QuickCard({
  icon: Icon, title, desc, onClick,
}: {
  icon: LucideIcon;
  title: string; desc: string; onClick: () => void;
}) {
  return (
    <button
      onClick={onClick}
      className="glass-card glass-card-hover group flex flex-col items-start p-5 text-left"
    >
      <div className="mb-3 grid h-10 w-10 place-items-center rounded-xl bg-amber/10 text-amber-glow">
        <Icon size={18} />
      </div>
      <div className="flex w-full items-center justify-between">
        <span className="font-medium text-warm-white">{title}</span>
        <ChevronRight size={16} className="text-warm-faint transition-transform group-hover:translate-x-1 group-hover:text-amber-glow" />
      </div>
      <p className="mt-1.5 text-xs leading-relaxed text-warm-muted">{desc}</p>
    </button>
  );
}

function SubjectCard({ subject, mastery }: { subject: string; mastery: number }) {
  const level = masteryToLevel(mastery);
  return (
    <div className="glass-card glass-card-hover flex items-center gap-3 p-4">
      <BulbIcon level={level} size={32} animate={level >= 2} />
      <div className="min-w-0 flex-1">
        <div className="flex items-center justify-between">
          <span className="text-sm font-medium text-warm-white">{subject}</span>
          <span className="font-mono text-xs text-amber-glow">{Math.round(mastery * 100)}%</span>
        </div>
        <div className="mt-2 h-1.5 overflow-hidden rounded-full bg-white/5">
          <div
            className="h-full rounded-full bg-gradient-to-r from-amber-dim to-amber-glow transition-all duration-700"
            style={{ width: `${mastery * 100}%` }}
          />
        </div>
      </div>
    </div>
  );
}

function SprintToggle() {
  const sprintMode = useStore((s) => s.sprintMode);
  const toggleSprint = useStore((s) => s.toggleSprint);
  return (
    <button
      onClick={toggleSprint}
      className={`relative h-7 w-12 rounded-full transition-colors duration-300 ${
        sprintMode ? "bg-teal-wire" : "bg-white/10"
      }`}
      aria-label="切换考前冲刺"
    >
      <span
        className={`absolute top-1 h-5 w-5 rounded-full bg-warm-white transition-all duration-300 ${
          sprintMode ? "left-6" : "left-1"
        }`}
      />
    </button>
  );
}

function getGreeting(): string {
  const h = new Date().getHours();
  if (h < 6) return "夜深了";
  if (h < 12) return "早上好";
  if (h < 14) return "中午好";
  if (h < 18) return "下午好";
  return "晚上好";
}

function formatDate(): string {
  const d = new Date();
  const days = ["日", "一", "二", "三", "四", "五", "六"];
  return `${d.getFullYear()}年${d.getMonth() + 1}月${d.getDate()}日 · 星期${days[d.getDay()]}`;
}
