import { useState, useRef, useEffect } from "react";
import { useStore } from "@/store/useStore";
import { SEED_KNOWLEDGE_POINTS, SEED_CARDS } from "@/lib/seedData";
import { Card, CardType, MemoryMethod } from "@/lib/types";
import { getMethod, MEMORY_METHODS } from "@/lib/memoryMethods";
import {
  Sparkles, Wand2, FileText, CheckCircle2, Loader2,
  Plus, RotateCw, Cpu, ListChecks, Layers, type LucideIcon,
} from "lucide-react";
import { cn } from "@/lib/utils";

type Phase = "idle" | "analyzing" | "matching" | "generating" | "done";

const STAGES = [
  { key: "analyze", label: "识别内容类型", icon: Cpu, hint: "解析知识点结构与学科属性" },
  { key: "match", label: "匹配记忆方法", icon: Layers, hint: "从 8 种方法中选择最优策略" },
  { key: "gen-cloze", label: "生成挖空题", icon: FileText, hint: "提取关键信息点构造填空" },
  { key: "gen-choice", label: "生成选择题", icon: ListChecks, hint: "构造干抚项与正确选项" },
  { key: "gen-flash", label: "生成闪卡", icon: Sparkles, hint: "生成正反面对应卡片" },
] as const;

// 预置示例（从种子知识点中挑选有代表性的几个）
const SAMPLE_PROMPTS = [
  "1644 清军入关",
  "线粒体——细胞的能量工厂",
  "二次方程求根公式",
  "词根 port 的含义",
  "牛顿第二定律 F=ma",
];

export default function Generate() {
  const [input, setInput] = useState("");
  const [phase, setPhase] = useState<Phase>("idle");
  const [stageIdx, setStageIdx] = useState(-1);
  const [results, setResults] = useState<Card[]>([]);
  const [added, setAdded] = useState(false);
  const timers = useRef<number[]>([]);

  const addGeneratedCards = useStore((s) => s.addGeneratedCards);
  const cards = useStore((s) => s.cards);

  useEffect(() => () => timers.current.forEach(clearTimeout), []);

  function generate(text: string) {
    if (!text.trim()) return;
    // 清理
    timers.current.forEach(clearTimeout);
    timers.current = [];
    setResults([]);
    setAdded(false);
    setPhase("analyzing");
    setStageIdx(0);

    // 模拟分阶段流式输出
    const generated = synthesizeCards(text);
    STAGES.forEach((_, i) => {
      const t = window.setTimeout(() => {
        setStageIdx(i);
        if (i === STAGES.length - 1) {
          // 最后阶段：逐步揭晓卡片
          const revealT = window.setTimeout(() => {
            setPhase("done");
            // 一张张揭晓
            generated.forEach((c, ci) => {
              const rt = window.setTimeout(() => {
                setResults((prev) => [...prev, c]);
              }, ci * 280);
              timers.current.push(rt);
            });
          }, 500);
          timers.current.push(revealT);
        }
      }, i * 900);
      timers.current.push(t);
    });
  }

  function reset() {
    timers.current.forEach(clearTimeout);
    timers.current = [];
    setPhase("idle");
    setStageIdx(-1);
    setResults([]);
    setAdded(false);
  }

  function addToLibrary() {
    if (results.length === 0) return;
    addGeneratedCards(results);
    setAdded(true);
  }

  const busy = phase !== "idle" && phase !== "done";

  return (
    <div className="animate-fade-up">
      <header className="mb-8">
        <p className="eyebrow mb-2">AI 卡片生成引擎</p>
        <h1 className="display text-3xl sm:text-4xl">
          输入知识点，<span className="text-amber-glow">30 秒生成一套记忆卡片</span>
        </h1>
        <p className="mt-2 max-w-2xl text-sm leading-relaxed text-warm-muted">
          AI 自动识别内容类型、匹配最优记忆方法，一次性输出挖空题、选择题、闪卡。
          把 Anki「30% 学习、70% 排版」的痛点彻底消除。
        </p>
      </header>

      {/* 输入区 */}
      <div className="glass-card p-6">
        <label className="mb-2 block text-xs uppercase tracking-widest text-warm-faint">知识点输入</label>
        <div className="flex flex-col gap-3 sm:flex-row">
          <input
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={(e) => e.key === "Enter" && generate(input)}
            placeholder="例如：光合作用的反应方程式"
            disabled={busy}
            className="flex-1 rounded-xl border border-white/10 bg-ink-950/60 px-4 py-3 text-warm-white outline-none transition-colors placeholder:text-warm-faint focus:border-amber/50 disabled:opacity-50"
          />
          <button
            onClick={() => generate(input)}
            disabled={busy || !input.trim()}
            className="btn-glow disabled:cursor-not-allowed disabled:opacity-40"
          >
            {busy ? <Loader2 size={18} className="animate-spin" /> : <Wand2 size={18} />}
            {busy ? "生成中" : "生成卡片"}
          </button>
        </div>
        <div className="mt-3 flex flex-wrap items-center gap-2">
          <span className="text-xs text-warm-faint">试试：</span>
          {SAMPLE_PROMPTS.map((p) => (
            <button
              key={p}
              onClick={() => { setInput(p); }}
              disabled={busy}
              className="rounded-full border border-white/10 bg-white/5 px-3 py-1 text-xs text-warm-muted transition-colors hover:border-amber/30 hover:text-amber-glow disabled:opacity-50"
            >
              {p}
            </button>
          ))}
        </div>
      </div>

      {/* 生成动画 */}
      {phase !== "idle" && (
        <div className="mt-6">
          {/* 阶段进度 */}
          {phase !== "done" && (
            <div className="glass-card p-6">
              <div className="flex items-center gap-2 text-sm text-amber-glow">
                <Sparkles size={16} className="animate-pulse-glow" />
                <span>AI 正在分析「{input}」</span>
              </div>
              <div className="mt-4 space-y-2.5">
                {STAGES.map((s, i) => {
                  const state = i < stageIdx ? "done" : i === stageIdx ? "active" : "pending";
                  return (
                    <div
                      key={s.key}
                      className={cn(
                        "flex items-center gap-3 rounded-lg px-3 py-2 transition-all duration-300",
                        state === "active" && "bg-amber/5",
                      )}
                    >
                      <div className={cn(
                        "grid h-7 w-7 place-items-center rounded-full border transition-all",
                        state === "done" && "border-amber/40 bg-amber/15 text-amber-glow",
                        state === "active" && "border-amber/60 bg-amber/10 text-amber-glow",
                        state === "pending" && "border-white/10 text-warm-faint",
                      )}>
                        {state === "done" ? <CheckCircle2 size={14} /> :
                         state === "active" ? <Loader2 size={14} className="animate-spin" /> :
                         <s.icon size={14} />}
                      </div>
                      <div className="flex-1">
                        <span className={cn(
                          "text-sm",
                          state === "pending" ? "text-warm-faint" : "text-warm-white",
                        )}>{s.label}</span>
                        {state === "active" && (
                          <span className="ml-2 text-xs text-warm-muted">{s.hint}</span>
                        )}
                      </div>
                      {state === "active" && (
                        <span className="font-mono text-xs text-amber-glow animate-blink">_</span>
                      )}
                    </div>
                  );
                })}
              </div>
            </div>
          )}

          {/* 结果卡片 */}
          {results.length > 0 && (
            <div className="animate-fade-up mt-6">
              <div className="mb-4 flex items-center justify-between">
                <h2 className="display text-xl">
                  生成完成 · <span className="text-amber-glow">{results.length}</span> 张卡片
                </h2>
                <div className="flex gap-2">
                  <button onClick={reset} className="btn-ghost !py-2">
                    <RotateCw size={14} /> 重新生成
                  </button>
                  <button
                    onClick={addToLibrary}
                    disabled={added}
                    className={cn("btn-glow !py-2 !px-4 text-sm", added && "!bg-emerald-500/20 !text-emerald-300 !shadow-none")}
                  >
                    {added ? <><CheckCircle2 size={14} /> 已加入</> : <><Plus size={14} /> 加入学习库</>}
                  </button>
                </div>
              </div>
              <div className="grid gap-4 md:grid-cols-3">
                {results.map((c, i) => (
                  <ResultCard key={c.id} card={c} index={i} />
                ))}
              </div>
              {added && (
                <p className="mt-4 text-center text-xs text-emerald-300/80">
                  已加入学习库，当前共 {cards.length} 张卡片，SM-2 算法将自动安排复习节奏。
                </p>
              )}
            </div>
          )}
        </div>
      )}

      {/* 空状态提示 */}
      {phase === "idle" && (
        <div className="mt-6 grid gap-3 sm:grid-cols-3">
          <FeatureChip icon={Cpu} title="智能识别" desc="自动判断术语/公式/时间线/对比等类型" />
          <FeatureChip icon={Layers} title="方法匹配" desc="8 种记忆方法后台自动择优" />
          <FeatureChip icon={Sparkles} title="多题型输出" desc="挖空 + 选择 + 闪卡一次成型" />
        </div>
      )}
    </div>
  );
}

function ResultCard({ card, index }: { card: Card; index: number }) {
  const method = getMethod(card.method);
  return (
    <div
      className="glass-card animate-fade-up p-5"
      style={{ animationDelay: `${index * 0.1}s` }}
    >
      <div className="mb-3 flex items-center justify-between">
        <span className="rounded-md bg-white/5 px-2 py-0.5 text-xs text-warm-muted">
          {typeLabel(card.type)}
        </span>
        <span className="text-xs text-amber-glow/80">{method.name}</span>
      </div>
      <p className="mb-3 font-serif text-base leading-relaxed text-warm-white">{card.front}</p>
      <div className="rounded-lg border border-amber/15 bg-amber/5 px-3 py-2">
        <span className="text-[10px] uppercase tracking-wider text-amber-glow/70">答案</span>
        <p className="mt-0.5 text-sm text-amber-glow">{card.back}</p>
      </div>
    </div>
  );
}

function FeatureChip({
  icon: Icon, title, desc,
}: { icon: LucideIcon; title: string; desc: string }) {
  return (
    <div className="glass-card flex items-start gap-3 p-4">
      <div className="grid h-9 w-9 shrink-0 place-items-center rounded-lg bg-amber/10 text-amber-glow">
        <Icon size={16} />
      </div>
      <div>
        <p className="text-sm font-medium text-warm-white">{title}</p>
        <p className="mt-0.5 text-xs leading-relaxed text-warm-muted">{desc}</p>
      </div>
    </div>
  );
}

function typeLabel(t: CardType): string {
  return t === "cloze" ? "挖空题" : t === "choice" ? "选择题" : "闪卡";
}

// 模拟 AI 生成 —— 优先匹配种子知识点，否则用模板合成
function synthesizeCards(text: string): Card[] {
  const seedKp = SEED_KNOWLEDGE_POINTS.find((k) => text.includes(k.title) || k.title.includes(text));
  if (seedKp) {
    // 复用种子卡片（生成新 id 避免冲突）
    // 从种子数据 import SEED_CARDS
    return getSeedCardsForKp(seedKp.id).map((c) => ({ ...c, id: `${c.id}-gen-${Date.now()}-${Math.random().toString(36).slice(2, 5)}` }));
  }
  // 模板合成
  const kpId = `kp-custom-${Date.now()}`;
  return [
    {
      id: `gen-cloze-${Date.now()}`,
      kpId,
      type: "cloze",
      method: "split",
      front: `${text} 的核心要点是 ______。`,
      back: "（请根据你的教材补充标准答案）",
      blank: "核心要点",
    },
    {
      id: `gen-choice-${Date.now()}`,
      kpId,
      type: "choice",
      method: "contrast",
      front: `关于「${text}」，下列说法正确的是？`,
      options: ["A 选项（待校对）", "B 选项（待校对）", "C 选项（正确）", "D 选项（待校对）"],
      answerIndex: 2,
      back: "AI 已生成选项框架，建议结合教材校对后使用。",
    },
    {
      id: `gen-flash-${Date.now()}`,
      kpId,
      type: "flash",
      method: "feynman",
      front: `用大白话讲清楚：${text}`,
      back: "试着对小学生讲一遍——讲不通的地方，就是没真正懂的地方。",
    },
  ];
}

function getSeedCardsForKp(kpId: string): Card[] {
  return SEED_CARDS.filter((c) => c.kpId === kpId).slice(0, 3);
}
