import { useState, useMemo, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import { useStore } from "@/store/useStore";
import { previewInterval, formatInterval } from "@/lib/sm2";
import { getMethod } from "@/lib/memoryMethods";
import { Card, Rating, SUBJECT_CONFIGS } from "@/lib/types";
import {
  ChevronLeft, RotateCcw, Check, X, Home as HomeIcon,
  Brain, Sparkles, Trophy, type LucideIcon,
} from "lucide-react";
import { cn } from "@/lib/utils";

export default function Review() {
  const navigate = useNavigate();
  const rateCard = useStore((s) => s.rateCard);
  const getCardSchedule = useStore((s) => s.getCardSchedule);
  const knowledgePoints = useStore((s) => s.knowledgePoints);
  const sprintMode = useStore((s) => s.sprintMode);
  const cards = useStore((s) => s.cards);
  const schedules = useStore((s) => s.schedules);
  const getDueCards = useStore((s) => s.getDueCards);

  // 复习队列（进入页面时固定，复习过程中不因评分改变而重排）
  const dueCards = useMemo(() => getDueCards(), [getDueCards, cards, schedules]);
  const [queue] = useState<Card[]>(() => [...dueCards]);
  const [idx, setIdx] = useState(0);
  const [flipped, setFlipped] = useState(false);
  const [stats, setStats] = useState({ again: 0, hard: 0, good: 0, easy: 0 });

  const current = queue[idx];
  const finished = idx >= queue.length;

  // 切卡时重置翻转
  useEffect(() => setFlipped(false), [idx]);

  const kp = useMemo(
    () => knowledgePoints.find((k) => k.id === current?.kpId),
    [current, knowledgePoints]
  );

  if (queue.length === 0) {
    return <EmptyState onBack={() => navigate("/")} />;
  }

  if (finished) {
    return <SessionSummary stats={stats} total={queue.length} onHome={() => navigate("/")} />;
  }

  const schedule = getCardSchedule(current.id);
  const preset = kp?.preset ?? "文科类";
  const method = getMethod(current.method);

  function handleRate(r: Rating) {
    rateCard(current.id, r);
    setStats((s) => ({ ...s, [r]: s[r] + 1 }));
    setIdx((i) => i + 1);
  }

  const progress = (idx / queue.length) * 100;
  const cfg = SUBJECT_CONFIGS[preset];

  return (
    <div className="animate-fade-up">
      {/* 顶栏 */}
      <div className="mb-6 flex items-center justify-between">
        <button onClick={() => navigate("/")} className="btn-ghost !py-2">
          <ChevronLeft size={16} /> 退出
        </button>
        <div className="flex items-center gap-3 text-xs text-warm-muted">
          <span className="rounded-full bg-amber/10 px-3 py-1 text-amber-glow">
            {cfg.preset} · EF {schedule.easeFactor}
          </span>
          {sprintMode && (
            <span className="rounded-full bg-teal-wire/15 px-3 py-1 text-teal-wire">冲刺 ×0.5</span>
          )}
        </div>
      </div>

      {/* 进度条 */}
      <div className="mb-6">
        <div className="mb-2 flex items-center justify-between text-xs text-warm-muted">
          <span>第 {idx + 1} / {queue.length} 张</span>
          <span>剩余 {queue.length - idx} 张</span>
        </div>
        <div className="h-2 overflow-hidden rounded-full bg-white/5">
          <div
            className="h-full rounded-full bg-gradient-to-r from-amber-dim via-amber to-amber-glow transition-all duration-500"
            style={{ width: `${progress}%` }}
          />
        </div>
      </div>

      {/* 卡片区 */}
      <div className="mx-auto max-w-2xl">
        <div
          className={cn("flip-container cursor-pointer", flipped && "flipped")}
          onClick={() => setFlipped((f) => !f)}
          style={{ height: 380 }}
        >
          <div className="flip-inner h-full w-full">
            {/* 正面 */}
            <div className="flip-face glass-card flex h-full w-full flex-col p-8">
              <div className="mb-4 flex items-center justify-between">
                <span className="rounded-md bg-white/5 px-2.5 py-1 text-xs text-warm-muted">
                  {typeLabel(current.type)}
                </span>
                <span className="flex items-center gap-1.5 text-xs text-amber-glow/80">
                  <Sparkles size={12} /> {method.name}
                </span>
              </div>
              <div className="flex flex-1 flex-col items-center justify-center text-center">
                <p className="mb-2 text-xs uppercase tracking-widest text-warm-faint">
                  {kp?.subjectLabel} · {kp?.title}
                </p>
                <CardFront card={current} />
              </div>
              <p className="mt-4 text-center text-xs text-warm-faint">
                {flipped ? "" : "点击卡片查看答案"}
              </p>
            </div>
            {/* 背面 */}
            <div className="flip-face flip-back glass-card flex h-full w-full flex-col p-8">
              <div className="mb-4 flex items-center justify-between">
                <span className="rounded-md bg-amber/10 px-2.5 py-1 text-xs text-amber-glow">答案</span>
                <span className="text-xs text-warm-muted">复习 {schedule.repetitions} 次</span>
              </div>
              <div className="flex flex-1 flex-col items-center justify-center text-center">
                <CardBack card={current} />
              </div>
            </div>
          </div>
        </div>

        {/* 评分条 */}
        <div className="mt-6">
          {!flipped ? (
            <button
              onClick={() => setFlipped(true)}
              className="btn-glow mx-auto flex w-full max-w-xs"
            >
              <Brain size={18} /> 显示答案
            </button>
          ) : (
            <div className="grid grid-cols-2 gap-3 sm:grid-cols-4">
              <RateBtn rating="again" preview={previewInterval(schedule, "again", preset, sprintMode)} onClick={handleRate} />
              <RateBtn rating="hard" preview={previewInterval(schedule, "hard", preset, sprintMode)} onClick={handleRate} />
              <RateBtn rating="good" preview={previewInterval(schedule, "good", preset, sprintMode)} onClick={handleRate} />
              <RateBtn rating="easy" preview={previewInterval(schedule, "easy", preset, sprintMode)} onClick={handleRate} />
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

function CardFront({ card }: { card: Card }) {
  if (card.type === "cloze") {
    return (
      <p className="font-serif text-2xl leading-relaxed text-warm-white sm:text-3xl">
        {renderCloze(card.front, card.blank)}
      </p>
    );
  }
  if (card.type === "choice") {
    return (
      <div className="w-full">
        <p className="mb-5 font-serif text-xl leading-relaxed text-warm-white sm:text-2xl">{card.front}</p>
        <div className="grid grid-cols-1 gap-2 text-left sm:grid-cols-2">
          {card.options?.map((opt, i) => (
            <div key={i} className="rounded-lg border border-white/10 bg-white/5 px-4 py-2.5 text-sm text-warm-muted">
              <span className="mr-2 font-mono text-amber-glow">{String.fromCharCode(65 + i)}</span>
              {opt}
            </div>
          ))}
        </div>
      </div>
    );
  }
  return <p className="font-serif text-2xl leading-relaxed text-warm-white sm:text-3xl">{card.front}</p>;
}

function CardBack({ card }: { card: Card }) {
  if (card.type === "choice") {
    return (
      <div className="w-full">
        <p className="mb-3 font-serif text-lg text-warm-muted line-through opacity-60">{card.front}</p>
        <p className="mb-4 text-2xl font-bold text-amber-glow">
          正确答案：{String.fromCharCode(65 + (card.answerIndex ?? 0))}
        </p>
        <p className="text-sm leading-relaxed text-warm-white">{card.back}</p>
      </div>
    );
  }
  return (
    <div className="w-full">
      <p className="mb-4 text-3xl font-bold text-amber-glow">{card.back}</p>
      {card.type === "flash" && (
        <p className="text-sm leading-relaxed text-warm-muted">{card.back}</p>
      )}
    </div>
  );
}

function RateBtn({
  rating, preview, onClick,
}: {
  rating: Rating; preview: number; onClick: (r: Rating) => void;
}) {
  const config: Record<Rating, { label: string; color: string; icon: LucideIcon }> = {
    again: { label: "生疏", color: "border-rose-400/40 text-rose-300 hover:bg-rose-400/10", icon: X },
    hard: { label: "困难", color: "border-amber/40 text-amber-glow hover:bg-amber/10", icon: RotateCcw },
    good: { label: "良好", color: "border-teal-wire/40 text-teal-wire hover:bg-teal-wire/10", icon: Check },
    easy: { label: "简单", color: "border-emerald-400/40 text-emerald-300 hover:bg-emerald-400/10", icon: Sparkles },
  };
  const c = config[rating];
  const Icon = c.icon;
  return (
    <button
      onClick={() => onClick(rating)}
      className={cn(
        "flex flex-col items-center gap-1 rounded-xl border bg-white/[0.02] py-3 transition-all duration-200",
        c.color
      )}
    >
      <Icon size={16} />
      <span className="text-sm font-medium">{c.label}</span>
      <span className="font-mono text-[10px] opacity-70">{formatInterval(preview)}</span>
    </button>
  );
}

function SessionSummary({
  stats, total, onHome,
}: {
  stats: { again: number; hard: number; good: number; easy: number };
  total: number; onHome: () => void;
}) {
  const correct = stats.good + stats.easy;
  const rate = total > 0 ? Math.round((correct / total) * 100) : 0;
  return (
    <div className="animate-fade-up mx-auto max-w-lg pt-10 text-center">
      <div className="mx-auto mb-6 grid h-20 w-20 place-items-center rounded-full bg-amber/10 shadow-glow">
        <Trophy size={36} className="text-amber-glow" />
      </div>
      <h1 className="display text-3xl">本次复习完成</h1>
      <p className="mt-2 text-sm text-warm-muted">你刚刚巩固了 {total} 个知识点</p>

      <div className="mt-8 glass-card p-6">
        <div className="mb-5 flex items-end justify-center gap-2">
          <span className="font-serif text-5xl font-black text-amber-glow">{rate}%</span>
          <span className="mb-1 text-sm text-warm-muted">正确率</span>
        </div>
        <div className="grid grid-cols-4 gap-2 text-center">
          <Stat label="生疏" value={stats.again} color="text-rose-300" />
          <Stat label="困难" value={stats.hard} color="text-amber-glow" />
          <Stat label="良好" value={stats.good} color="text-teal-wire" />
          <Stat label="简单" value={stats.easy} color="text-emerald-300" />
        </div>
      </div>

      <button onClick={onHome} className="btn-glow mt-8 mx-auto">
        <HomeIcon size={18} /> 返回首页
      </button>
    </div>
  );
}

function Stat({ label, value, color }: { label: string; value: number; color: string }) {
  return (
    <div>
      <div className={cn("font-serif text-2xl font-black", color)}>{value}</div>
      <div className="mt-1 text-xs text-warm-muted">{label}</div>
    </div>
  );
}

function EmptyState({ onBack }: { onBack: () => void }) {
  return (
    <div className="animate-fade-up mx-auto max-w-md pt-20 text-center">
      <div className="mx-auto mb-6 grid h-20 w-20 place-items-center rounded-full bg-amber/10">
        <Check size={36} className="text-amber-glow" />
      </div>
      <h1 className="display text-2xl">今日复习已清空</h1>
      <p className="mt-2 text-sm text-warm-muted">
        所有到期卡片都已复习完毕。SM-2 算法会在合适的时机把它们再次带到你面前。
      </p>
      <button onClick={onBack} className="btn-glow mt-8 mx-auto">
        <HomeIcon size={18} /> 返回首页
      </button>
    </div>
  );
}

function renderCloze(front: string, blank?: string) {
  if (!blank) return front;
  const parts = front.split(blank);
  return (
    <>
      {parts.map((p, i) => (
        <span key={i}>
          {p}
          {i < parts.length - 1 && (
            <span className="mx-1 inline-block min-w-[3em] border-b-2 border-dashed border-amber/60 text-amber/40">
              &nbsp;?&nbsp;
            </span>
          )}
        </span>
      ))}
    </>
  );
}

function typeLabel(t: Card["type"]): string {
  return t === "cloze" ? "挖空题" : t === "choice" ? "选择题" : "闪卡";
}
